let palette = ['#1160c6', '#fdd900', '#e6302b', '#ffffff'];
let ctx;
let centerX, centerY;
let walkers = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	for (let i = 0; i < 80; i++) {
		let x = random(width);
		let y = random(height);
		let d = width / random(60, 90);
		let clr = palette[i % palette.length];
		walkers.push(new Walker(x, y, d, clr));
	}
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	background('#000000');

	for (let i = 0; i < walkers.length; i++) {
		let c1 = walkers[i];
		for (let j = i + 1; j < walkers.length; j++) {
			let c2 = walkers[j];
			let dx = c2.x - c1.x;
			let dy = c2.y - c1.y;
			let distance = sqrt(dx * dx + dy * dy);
			let minDist = (c1.d + c2.d) * 3;

			if (distance < minDist && distance > 0) {
				let force = (minDist - distance) * 0.002;
				let nx = dx / distance;
				let ny = dy / distance;
				c1.vx -= force * nx;
				c1.vy -= force * ny;
				c2.vx += force * nx;
				c2.vy += force * ny;
			}
		}
	}

	for (let i of walkers) {
		i.run();
	}

}

