class Walker {
	constructor(x, y, d, clr) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.clr = clr;
		this.footprints = [];
		let trailLength = int(random(50, 80));
		for (let i = 0; i < trailLength; i++) {
			this.footprints.push(createVector(this.x, this.y));
		}
		this.segLength = width / 700;

		this.spd = width / 300;

		this.vx = random([-1, 1]) * this.spd * random(0.1, 1);
		this.vy = random([-1, 1]) * this.spd * random(0.1, 1);
		this.orbs = [];

	}

	show() {

		for (let i of this.orbs) {
			i.run();
		}

		noFill();
		stroke(this.clr);

		this.dragSegment(0, this.x, this.y);
		for (let i = 0; i < this.footprints.length - 1; i++) {
			let f = this.footprints[i];
			let sw = map(i, 0, this.footprints.length, this.d, 0);
			strokeWeight(sw);
			this.dragSegment(i + 1, f.x, f.y);
		}
	}

	update() {
		this.x += this.vx;
		this.y += this.vy;

		let r = this.d / 2
		if (this.x <= r || width - r <= this.x) {
			this.vx *= -1;
			this.vx = random([-1, 1]) * this.spd * random(0.1, 1);
		}
		if (this.y <= r || height - r <= this.y) {
			this.vy *= -1;
			this.vy = random([-1, 1]) * this.spd * random(0.1, 1);
		}

		let radius = this.d / 2;
		this.x = constrain(this.x, radius, width - radius);
		this.y = constrain(this.y, radius, height - radius);

		if (random() < 0.2) {
			this.orbs.push(new Orb(this.x, this.y, this.d, this.clr));
		}

		for (let i = 0; i < this.orbs.length; i++) {
			let o = this.orbs[i];
			if (o.isDead == true) {
				this.orbs.splice(i, 1);
			}
		}
	}

	run() {
		this.show();
		this.update();
	}

	dragSegment(i, xin, yin) {
		let f = this.footprints[i];
		let dx = xin - f.x;
		let dy = yin - f.y;
		let angle = atan2(dy, dx);
		f.x = xin - cos(angle) * this.segLength;
		f.y = yin - sin(angle) * this.segLength;
		this.segment(f.x, f.y, angle);
	}

	segment(x, y, a) {
		push();
		translate(x, y);
		rotate(a);
		line(0, 0, this.segLength, 0);
		pop();
	}
}

class Orb {
	constructor(x, y, d, clr) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.clr = color(clr);
		this.span = 80;
		this.life = this.span;
		let a = random(TAU);
		let r = (width / 40) * random();
		this.tgtX = this.x + r * cos(a);
		this.tgtY = this.y + r * sin(a);
		this.curX = x;
		this.curY = y;
		this.curD = d;
		this.isDead = false;
	}

	show() {
		noStroke();
		this.clr.setAlpha(100);
		fill(this.clr);
		circle(this.curX, this.curY, this.curD);
	}

	update() {
		this.life--;
		if (this.life <= 0) {
			this.isDead = true;
		}
		let n = norm(this.life, this.span, 0);
		this.curX = lerp(this.x, this.tgtX, n);
		this.curY = lerp(this.y, this.tgtY, n);
		this.curD = lerp(this.d, 0, n ** 0.5);
	}

	run() {
		this.show();
		this.update();
	}
}

